    def test_update_existing_environment_variable(self, api_client, valid_context_id, 
                                                env_var_name, env_var_value, auth_headers):
        """Test updating an existing environment variable."""
        endpoint = self.ENDPOINT.format(context_id=valid_context_id, env_var_name=env_var_name)
        
        # First, create the variable
        initial_payload = {"value": env_var_value}
        initial_response = api_client.put(endpoint, headers=auth_headers, json=initial_payload)
        
        # Verify creation was successful
        assert initial_response.status_code == 200
        
        # Now update with a new value
        updated_payload = {"value": f"{env_var_value}-updated"}
        update_response = api_client.put(endpoint, headers=auth_headers, json=updated_payload)
        
        # Verify update was successful
        assert update_response.status_code == 200
        
        # Check that timestamps differ
        initial_data = initial_response.json()
        updated_data = update_response.json()
        
        # Convert string timestamps to datetime objects for comparison
        initial_updated_at = datetime.fromisoformat(initial_data["updated_at"].replace("Z", "+00:00"))
        current_updated_at = datetime.fromisoformat(updated_data["updated_at"].replace("Z", "+00:00"))
        
        # The updated_at timestamp should be newer
        assert current_updated_at >= initial_updated_at
